// Normalize Accounts From Feishu 公众号 List
const resp = items[0]?.json || {};
if (resp.code !== undefined && resp.code !== 0) {
  throw new Error('飞书公众号 List 查询失败：' + JSON.stringify(resp).slice(0, 500));
}
const records = resp.data?.items || [];
if (records.length === 0) {
  throw new Error('没有找到启用的公众号，pipeline_key=' + $('Execute Sub-workflow Trigger').first().json.pipeline_key);
}

// P1：安全优先。当前版本仍只取 page_size=100，若被截断则直接失败，避免静默漏抓账号。
if (resp.data?.has_more) {
  throw new Error('公众号 List 查询结果超过 page_size=100，当前 Flow 未启用分页。为避免漏账号，本次执行已中断。请增加分页读取后再运行。');
}

function fsText(v) {
  if (!v) return '';
  if (Array.isArray(v)) return v.map(x => x?.text || '').join('').trim();
  if (typeof v === 'object') return (v.text || v.link || '').trim();
  return String(v).trim();
}
const listMeta = {
  list_total: records.length,
  list_page: 1,
  list_page_size: 100,
  list_truncated: Boolean(resp.data?.has_more),
};
const baseUrl = 'http://wechat2rss:8080';
const output = [];
for (const [i, rec] of records.entries()) {
  const fields = rec.fields || {};
  const bizId = fsText(fields.biz_id);
  const accountName = fsText(fields['账号名称']);
  if (!bizId) continue;
  const feedJsonUrl = `${baseUrl}/feed/${encodeURIComponent(bizId)}.json`;
  output.push({ json: {
    account_index: i,
    biz_id: bizId,
    account_name: accountName,
    feed_link: '',
    feed_json_url: feedJsonUrl,
    stage1_list_meta: listMeta,
  }});
}
return output;

// Code Node: Normalize And Filter Feed Articles (V2 optimized - 全量 markdown，清洗噪音，记录失败账号)
function stableHash(str) {
  str = String(str||''); let h1=0xdeadbeef^str.length, h2=0x41c6ce57^str.length;
  for(let i=0,ch;i<str.length;i++){ch=str.charCodeAt(i);h1=Math.imul(h1^ch,2654435761);h2=Math.imul(h2^ch,1597334677);}
  h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909);
  h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909);
  return 'wx_'+(4294967296*(2097151&h2)+(h1>>>0)).toString(36);
}

function decodeHtml(t) {
  if(!t||typeof t!=='string') return '';
  return t.replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>')
    .replace(/&quot;/g,'"').replace(/&#39;/g,"'")
    .replace(/&#x([0-9a-f]+);/gi,(_,h)=>String.fromCharCode(parseInt(h,16)))
    .replace(/&#(\d+);/g,(_,c)=>String.fromCharCode(parseInt(c,10)));
}

function stripHtml(t){ return decodeHtml(String(t||'').replace(/<[^>]+>/g,'')).replace(/\s+/g,' ').trim(); }

function cleanMarkdown(md) {
  if(!md||typeof md!=='string') return '';

  // 1. 删除 Markdown 图片
  md = md.replace(/!\[[^\]]*\]\([^)]+\)/g, '');

  // 2. Markdown 链接 → 纯文本（空文本则整段删除）
  md = md.replace(/\[([^\]]*)\]\([^)]+\)/g, (_, text) => text.trim());

  // 3. 逐行清洗
  const noiseKeywords = [
    '阅读原文','点击蓝字','长按识别二维码','扫码关注','关注公众号','关注我们',
    '点赞','在看','喜欢','分享','转载','版权声明','商务合作','广告',
    '跳转微信','原创声明','禁止二改','禁止抄袭','禁止洗稿',
  ];

  const lines = md.split('\n').map(l => l.trim()).filter(line => {
    if(!line) return true; // 空行保留，后面统一压缩

    // 删除独立 URL 行
    if(/^https?:\/\/\S+$/.test(line)) return false;
    if(/^\/\/\S+$/.test(line)) return false;

    // 删除纯装饰符号行（3+ 重复非文字字符）
    if(/^[\-_*—=~·•●○▲▼▸►◆□■/\\|！☆★♥♦#@%&\s]{3,}$/.test(line)) return false;

    // 删除短噪音行（去掉格式符号后 ≤30 字，且含噪音关键词）
    const plain = line.replace(/[*_~`#>]/g, '').trim();
    if(plain.length <= 30 && noiseKeywords.some(k => line.includes(k))) return false;

    return true;
  });

  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function htmlToMarkdown(html) {
  if(!html||typeof html!=='string') return '';
  let t = html;

  // 1. 删除媒体/无用块
  t = t
    .replace(/<script[\s\S]*?<\/script>/gi,'')
    .replace(/<style[\s\S]*?<\/style>/gi,'')
    .replace(/<svg[\s\S]*?<\/svg>/gi,'')
    .replace(/<video[\s\S]*?<\/video>/gi,'')
    .replace(/<audio[\s\S]*?<\/audio>/gi,'')
    .replace(/<iframe[\s\S]*?<\/iframe>/gi,'')
    .replace(/<canvas[\s\S]*?<\/canvas>/gi,'');

  // 2. 删除图片
  t = t.replace(/<img[^>]*>/gi,'');

  // 3. 链接只保留文本（空文本则删除）
  t = t.replace(/<a[^>]*>([\s\S]*?)<\/a>/gi,(_, inner) => {
    const text = inner.replace(/<[^>]+>/g,'').trim();
    return text||'';
  });

  // 4. 块级结构
  t = t
    .replace(/<br\s*\/?>/gi,'\n')
    .replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi,'\n# $1\n')
    .replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi,'\n## $1\n')
    .replace(/<h3[^>]*>([\s\S]*?)<\/h3>/gi,'\n### $1\n')
    .replace(/<h4[^>]*>([\s\S]*?)<\/h4>/gi,'\n#### $1\n')
    .replace(/<p[^>]*>([\s\S]*?)<\/p>/gi,'\n$1\n')
    .replace(/<li[^>]*>([\s\S]*?)<\/li>/gi,'\n- $1')
    .replace(/<blockquote[^>]*>([\s\S]*?)<\/blockquote>/gi,'\n> $1\n');

  // 5. 行内结构
  t = t
    .replace(/<(strong|b)[^>]*>([\s\S]*?)<\/\1>/gi,'**$2**')
    .replace(/<(em|i)[^>]*>([\s\S]*?)<\/\1>/gi,'*$2*')
    .replace(/<code[^>]*>([\s\S]*?)<\/code>/gi,'`$1`');

  // 6. 去掉剩余 HTML 标签
  t = t.replace(/<[^>]+>/g,'');

  // 7. HTML 实体解码，再执行 cleanMarkdown
  return cleanMarkdown(decodeHtml(t));
}

function parseDate(v) {
  if(v===null||v===undefined||v==='') return null;
  if(typeof v==='number'){ const ms=v<1e12?v*1000:v; const d=new Date(ms); return isNaN(d)?null:d; }
  const r=String(v).trim();
  if(/^\d+$/.test(r)){ const n=Number(r); const ms=n<1e12?n*1000:n; const d=new Date(ms); return isNaN(d)?null:d; }
  const d=new Date(r.includes('T')?r:r.replace(' ','T')); return isNaN(d)?null:d;
}
function pickFeedItems(feed) {
  if(Array.isArray(feed)) return feed;
  if(!feed||typeof feed!=='object') return [];
  for(const k of ['items','entries','data']){ if(Array.isArray(feed[k])) return feed[k]; }
  if(Array.isArray(feed.data?.items)) return feed.data.items;
  return [];
}
function firstVal(...vals){ for(const v of vals){ if(v!==null&&v!==undefined&&String(v).trim()!=='') return v; } return ''; }
function safeErrSummary(obj) {
  try { return JSON.stringify(obj).slice(0, 500); } catch { return String(obj).slice(0, 500); }
}

const windowDays = Number($('Execute Sub-workflow Trigger').first().json.window_days) || 7;
const afterTime = Date.now() - windowDays*24*60*60*1000;
const accountItems = $('Normalize Accounts').all();
const output = [];

for(let i=0;i<items.length;i++){
  const feed=items[i].json||{};
  const account=accountItems[i]?.json||{};

  // P3：HTTP Request continueOnFail 后，失败账号不再静默丢失，写入 summary.failed_accounts。
  const hasFeedError = Boolean(feed.error || feed.err || feed.message === 'ERROR' || feed.status === 'error');
  if(hasFeedError){
    output.push({ json: {
      _stage1_failed_account: true,
      account_index: account.account_index,
      biz_id: account.biz_id || '',
      account_name: account.account_name || '',
      feed_json_url: account.feed_json_url || '',
      error: safeErrSummary(feed.error || feed.err || feed),
    }});
    continue;
  }

  const feedItems=pickFeedItems(feed);
  for(const it of feedItems){
    const title=stripHtml(firstVal(it.title));
    const url=String(firstVal(it.url,it.external_url,it.link,it.guid,it.id)).trim();
    if(!title&&!url) continue;
    const publishedRaw=firstVal(it.date_published,it.date_modified,it.published,it.updated,it.pubDate,it.created,it.create_time);
    const publishedDate=parseDate(publishedRaw);
    if(publishedDate&&publishedDate.getTime()<afterTime) continue;
    const contentHtml=String(firstVal(it.content_html,it.content,it.html,it.raw_html));
    const contentText=stripHtml(firstVal(it.content_text,it.summary,it.description,it.desc));
    // V2：全量 markdown，清洗图片/链接/噪音，不截断正文
    const markdown=contentHtml?htmlToMarkdown(contentHtml):cleanMarkdown(String(contentText||'').trim());
    const publishTime=publishedDate?publishedDate.toISOString():String(publishedRaw||'');
    const accountBizId=String(firstVal(account.biz_id,it.biz_id,it.biz,it.bid));
    const accountName=String(firstVal(account.account_name,it.biz_name,feed.title));
    const idSeed=firstVal(url,it.guid,it.id,['wechat2rss',accountBizId,publishTime,title||url].filter(Boolean).join(':'));
    if (!markdown) continue;
    output.push({ json: {
      article_id: stableHash(idSeed),
      biz_id: accountBizId,
      account_name: accountName,
      title,
      url,
      publish_time: publishTime,
      markdown_content: markdown,
      source: 'wechat2rss_feed_json',
      monitor_status: 'new',
    }});
  }
}
return output;

// Code Node: Build Stage1 Summary
function readSafe(name) { try { return $(name).all(); } catch { return []; } }
const articleItems = items.filter(i => i.json?.article_id);
const failedAccounts = items
  .filter(i => i.json?._stage1_failed_account)
  .map(i => ({
    account_index: i.json.account_index,
    biz_id: i.json.biz_id || '',
    account_name: i.json.account_name || '',
    feed_json_url: i.json.feed_json_url || '',
    error: i.json.error || '',
  }));
const accountItems = readSafe('Normalize Accounts');
const firstMeta = accountItems.find(i => i.json?.stage1_list_meta)?.json.stage1_list_meta || {};
const articles = articleItems.map(i => i.json);
return [{ json: {
  workflow: 'WeChat2RSS V2 Stage1 Main Optimized P0-P3',
  account_count: accountItems.length,
  article_count: articles.length,
  failed_account_count: failedAccounts.length,
  failed_accounts: failedAccounts,
  window_days: Number($('Execute Sub-workflow Trigger').first().json.window_days) || 7,
  list_total: firstMeta.list_total ?? accountItems.length,
  list_truncated: Boolean(firstMeta.list_truncated),
  generated_at: new Date().toISOString(),
  articles,
}}];

// Code Node: Prepare Feishu Base Payload (V2 Stage1 optimized)
// Stage1 只写基础字段；create/update 均不写 monitor_status，避免覆盖后续流程状态。
function parseDate(v) {
  if(v===null||v===undefined||v==='') return null;
  if(typeof v==='number'){ const ms=v<1e12?v*1000:v; const d=new Date(ms); return isNaN(d.getTime())?null:d; }
  const r=String(v).trim();
  if(/^\d+$/.test(r)){ const n=Number(r); const ms=n<1e12?n*1000:n; const d=new Date(ms); return isNaN(d.getTime())?null:d; }
  const d=new Date(r.includes('T')?r:r.replace(' ','T')); return isNaN(d.getTime())?null:d;
}

return items.map(item => {
  const a = item.json || {};
  const publishDate = parseDate(a.publish_time);
  const publishTimestamp = publishDate ? publishDate.getTime() : null;
  const url = String(a.url || '').trim();
  const title = String(a.title || '').trim();
  const markdown = String(a.markdown_content || '');

  const baseFields = {};
  if (title)            baseFields['标题'] = title;
  if (markdown)         baseFields['markdown'] = markdown;
  if (publishTimestamp) baseFields['发布时间'] = publishTimestamp;
  if (url)              baseFields['地址'] = { text: title || url, link: url, type: 'url' };
  if (a.account_name)   baseFields['账号'] = String(a.account_name);
  if (a.article_id)     baseFields['article_id'] = String(a.article_id);

  return { json: {
    ...a,
    publish_time_ms: publishTimestamp,
    feishu_create_fields: { ...baseFields },
    feishu_update_fields: baseFields,
  }};
});

// Code Node: Build Article Upsert Summary
// 支持 create/update API 响应，也支持 skip unchanged 直接通过。
// 任何 Feishu 写入错误都直接抛出，避免 continueOnFail 后被误认为成功。
function fsVal(v) {
  if (!v) return '';
  if (Array.isArray(v)) return v.map(x => x?.text || '').join('').trim();
  if (typeof v === 'object') return (v.link || v.text || '').trim();
  return String(v).trim();
}
function summarizeError(j) {
  try { return JSON.stringify(j).slice(0, 800); } catch { return String(j).slice(0, 800); }
}

return items.map(i => {
  const j = i.json || {};

  if (j.error || (j.code !== undefined && j.code !== 0)) {
    throw new Error('飞书写入失败：' + summarizeError(j));
  }

  const rawArticleId =
    j.article_id ||
    j.data?.record?.fields?.article_id ||
    j.record?.fields?.article_id ||
    j.fields?.article_id ||
    j.feishu_create_fields?.article_id ||
    j.feishu_update_fields?.article_id ||
    '';
  const articleId = fsVal(rawArticleId) || String(rawArticleId || '').trim();

  if (!articleId) {
    throw new Error('无法从 create/update/skip 结果中恢复 article_id：' + summarizeError(j));
  }

  return { json: {
    ...j,
    article_id: articleId,
    _stage1_upsert_done: true,
    _stage1_action_done: j.action || 'write',
  }};
});

const sd = $getWorkflowStaticData('global');

let execId = '';
try { execId = String($execution?.id || ''); } catch (e) {}
if (!execId) {
  try { execId = String($('Build Stage1 Summary').first().json.generated_at || ''); } catch (e) {}
}
if (!execId) {
  throw new Error('无法获取 execution id / generated_at');
}

// 并发安全：每个 execution 用独立 bucket，避免多个 Entry 同时触发同一子流程时互相清空计数
if (!sd.barriers || typeof sd.barriers !== 'object') sd.barriers = {};
if (!sd.barriers[execId]) {
  sd.barriers[execId] = { seen: {}, triggered: false, created_at: Date.now() };
}
const bucket = sd.barriers[execId];

for (const item of items) {
  const j = item.json || {};
  const articleId =
    j.article_id ||
    j.fields?.article_id ||
    j.feishu_create_fields?.article_id ||
    j.feishu_update_fields?.article_id;
  if (articleId) {
    bucket.seen[String(articleId)] = true;
  }
}

const processed = Object.keys(bucket.seen).length;

let total = 0;
try {
  total = $('Aggregate Existing Map And Decide').all().filter(i => i.json?.article_id).length;
} catch (e) {}
if (!total || total <= 0) {
  throw new Error('决策后的 article_count 为空或 <= 0，无法判断是否完成 upsert/skip');
}

let result = [];
if (processed >= total && !bucket.triggered) {
  bucket.triggered = true;
  result = [{ json: {
    barrier_passed: true,
    processed,
    total,
    article_ids: Object.keys(bucket.seen),
    execution_id: execId,
    triggered_at: new Date().toISOString(),
  }}];
}

// 清理：删除超过 1 小时的旧 bucket（无论是否触发），避免 staticData 无限膨胀
const TTL_MS = 60 * 60 * 1000;
const now = Date.now();
for (const k of Object.keys(sd.barriers)) {
  const b = sd.barriers[k];
  if (b && b.created_at && (now - b.created_at) > TTL_MS) {
    delete sd.barriers[k];
  }
}

return result;

// Prepare Visibility Check
// 构造 OR filter，每批最多 50 个 article_id（飞书 API 单层 conditions 上限）
const CHUNK_SIZE = 50;
const articleIds = ($json.article_ids || []).filter(Boolean);
if (articleIds.length === 0) {
  throw new Error('Barrier 输出中无 article_ids，无法做可见性检查');
}
const chunks = [];
for (let i = 0; i < articleIds.length; i += CHUNK_SIZE) {
  chunks.push(articleIds.slice(i, i + CHUNK_SIZE));
}
return chunks.map(chunk => ({
  json: {
    article_ids: articleIds,
    total_expected: articleIds.length,
    filter_body: JSON.stringify({
      field_names: ['article_id', 'markdown', '\u5730\u5740'],
      filter: { conjunction: 'or', conditions: chunk.map(id => ({
        field_name: 'article_id',
        operator: 'is',
        value: [String(id)]
      }))},
      page_size: 100
    })
  }
}));

// Verify Count
// 飞书字段值统一用富文本解包：纯文本字段=[{text,type}]，URL字段={link,text}
function fsVal(v) {
  if (v === null || v === undefined || v === '') return '';
  if (Array.isArray(v)) return v.map(x => x?.text || x?.link || '').join('').trim();
  if (typeof v === 'object') return (v.link || v.text || '').trim();
  return String(v).trim();
}

const resp = items[0]?.json || {};
const records = resp.data?.items || resp.items || [];

let expectedIds = [];
try {
  const pcs = $('Prepare Visibility Check').all();
  for (const it of pcs) {
    for (const id of (it.json?.article_ids || [])) expectedIds.push(String(id).trim());
  }
  expectedIds = [...new Set(expectedIds.filter(Boolean))];
} catch (e) {}
if (expectedIds.length === 0) throw new Error('Verify Count：无法获取期望的 article_ids');

// 以解包后的 article_id 为 key 建索引
const foundMap = {};
for (const rec of records) {
  const fields = rec.fields || {};
  const aid = fsVal(fields.article_id);
  if (aid) foundMap[aid] = fields;
}

const missing = [];
const noMarkdown = [];
const noUrl = [];

for (const id of expectedIds) {
  const sid = String(id).trim();
  if (!foundMap[sid]) { missing.push(sid); continue; }
  const f = foundMap[sid];
  if (!fsVal(f.markdown || f['摘要'])) noMarkdown.push(sid);
  if (!fsVal(f['地址'] || f.url)) noUrl.push(sid);
}

const errors = [];
if (missing.length) errors.push('未在飞书找到：' + missing.join(', '));
if (noMarkdown.length) errors.push('markdown 为空：' + noMarkdown.join(', '));
if (noUrl.length) errors.push('地址为空：' + noUrl.join(', '));

if (errors.length) throw new Error('飞书可见性检查失败 | ' + errors.join(' | '));

return [{ json: { visibility_check: 'passed', found: Object.keys(foundMap).length, expected: expectedIds.length, article_ids: expectedIds } }];

// Aggregate Search Results
// 合并多批飞书查询结果，输出单个 item 供 Verify Count 使用
const allRecords = [];
for (const item of items) {
  const records = item.json?.data?.items || item.json?.items || [];
  allRecords.push(...records);
}
return [{ json: { data: { items: allRecords } } }];

// Deduplicate Articles by article_id
// 同一个 article_id 若在本轮重复出现，只保留第一条，避免重复查/写飞书。
const seen = new Set();
const output = [];
for (const item of items) {
  const j = item.json || {};
  const id = String(j.article_id || '').trim();
  if (!id) continue;
  if (seen.has(id)) continue;
  seen.add(id);
  output.push(item);
}
return output;

// Prepare Existing Check Chunks
// P0：批量查询本轮 article_id 是否已存在，每批最多 50 个，减少逐篇 Search。
const CHUNK_SIZE = 50;
const articleIds = items.map(i => String(i.json?.article_id || '').trim()).filter(Boolean);
if (articleIds.length === 0) {
  throw new Error('Prepare Existing Check Chunks：无 article_id，无法查询飞书已存在记录');
}
const chunks = [];
for (let i = 0; i < articleIds.length; i += CHUNK_SIZE) {
  chunks.push(articleIds.slice(i, i + CHUNK_SIZE));
}
return chunks.map(chunk => ({
  json: {
    article_ids: articleIds,
    total_expected: articleIds.length,
    filter_body: JSON.stringify({
      field_names: ['article_id', '标题', '发布时间', '地址', '账号'],
      filter: { conjunction: 'or', conditions: chunk.map(id => ({
        field_name: 'article_id',
        operator: 'is',
        value: [String(id)]
      }))},
      page_size: 100
    })
  }
}));

// Aggregate Existing Map And Decide
// 合并批量查询结果，并判断每篇文章 create / update / skip。
function fsVal(v) {
  if (!v) return '';
  if (Array.isArray(v)) return v.map(x => x?.text || '').join('').trim();
  if (typeof v === 'object') return (v.link || v.text || '').trim();
  return String(v).trim();
}
function normText(v) {
  return String(fsVal(v) || '').replace(/\r\n/g, '\n').trim();
}
function normUrl(v) {
  if (!v) return '';
  if (Array.isArray(v)) return v.map(x => x?.link || x?.text || '').join('').trim();
  if (typeof v === 'object') return String(v.link || v.text || '').trim();
  return String(v).trim();
}
function normTime(v) {
  const raw = fsVal(v);
  if (raw === '') return '';
  const n = Number(raw);
  if (!Number.isNaN(n)) return String(n);
  const d = new Date(raw);
  if (!Number.isNaN(d.getTime())) return String(d.getTime());
  return String(raw).trim();
}
function summarizeError(j) {
  try { return JSON.stringify(j).slice(0, 800); } catch { return String(j).slice(0, 800); }
}

const existingMap = {};
for (const item of items) {
  const resp = item.json || {};
  if (resp.error || (resp.code !== undefined && resp.code !== 0)) {
    throw new Error('批量查询飞书已有记录失败：' + summarizeError(resp));
  }
  const records = resp.data?.items || resp.items || resp.records || resp.data?.records || [];
  for (const rec of records) {
    const fields = rec.fields || {};
    const aid = normText(fields.article_id);
    if (!aid) continue;
    existingMap[aid] = {
      record_id: rec.record_id || rec.id || '',
      fields,
    };
  }
}

const sourceArticles = $('Prepare Feishu Base Payload').all().filter(i => i.json?.article_id);
const output = [];
for (const item of sourceArticles) {
  const a = item.json || {};
  const id = String(a.article_id || '').trim();
  const ex = existingMap[id];
  if (!ex) {
    output.push({ json: { ...a, action: 'create', existing_record_id: '', changed_fields: ['__new_record__'] } });
    continue;
  }

  const fields = ex.fields || {};
  const changed = [];
  if (normText(fields['标题']) !== normText(a.feishu_update_fields?.['标题'])) changed.push('标题');
  if (normTime(fields['发布时间']) !== normTime(a.feishu_update_fields?.['发布时间'])) changed.push('发布时间');
  if (normUrl(fields['地址']) !== normUrl(a.feishu_update_fields?.['地址'])) changed.push('地址');
  if (normText(fields['账号']) !== normText(a.feishu_update_fields?.['账号'])) changed.push('账号');

  if (changed.length > 0) {
    if (!ex.record_id) {
      throw new Error('已存在记录缺少 record_id，无法 update：article_id=' + id);
    }
    output.push({ json: {
      ...a,
      action: 'update',
      existing_record_id: ex.record_id,
      changed_fields: changed,
    }});
  } else {
    output.push({ json: {
      ...a,
      action: 'skip',
      existing_record_id: ex.record_id,
      changed_fields: [],
      skip_reason: 'unchanged',
    }});
  }
}

return output;
